const $=id=>document.getElementById(id);
const token=document.querySelector('meta[name=collector-token]').content;
let state={accounts:[],presets:[],total:0},applied={},page=1,pages=1,visible=[],selected=new Set(),mode='links',querySeq=0;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,data={},binary=false){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Collector-Token':token},body:JSON.stringify(data)});if(!r.ok){let j;try{j=await r.json()}catch{}throw new Error(j?.error||'操作未完成，请稍后重试')}return binary?r.blob():r.json()}
function status(message,error=false){$('status').hidden=false;$('status').className='status'+(error?' error':'');$('status').textContent=message}
function fail(e){status(e.message||String(e),true)}
function filter(){return {accounts:[...document.querySelectorAll('#accounts input:checked')].map(x=>x.value),start:$('start').value,end:$('end').value,include:$('include').value,exclude:$('exclude').value,mode:document.querySelector('[name=mode]:checked').value,scope:$('scope').value,original:$('original').checked}}
function setFilter(f={}){document.querySelectorAll('#accounts input').forEach(x=>x.checked=(f.accounts||[]).includes(x.value));['start','end','include','exclude'].forEach(k=>$(k).value=f[k]||'');document.querySelector(`[name=mode][value=${f.mode==='all'?'all':'any'}]`).checked=true;$('scope').value=f.scope||'title';$('original').checked=!!f.original}
async function loadState(){const current=filter(),preset=$('preset').value;state=await api('state');$('accounts').innerHTML=state.accounts.map(a=>`<label><input type="checkbox" value="${escapeHTML(a.name)}"><span>${escapeHTML(a.name)} <small class="hint">${a.articleCount??0} 篇</small></span></label>`).join('')||'<p class="hint">导入文章表或添加公众号后，会显示在这里。</p>';$('preset').innerHTML='<option value="">选择方案</option>'+state.presets.map((p,i)=>`<option value="${i}">${escapeHTML(p.name)}</option>`).join('');$('preset').value=preset;setFilter(current);$('summary').textContent=`本机已保存 ${state.total.toLocaleString()} 篇文章 · ${state.accounts.length} 个公众号`;renderSources()}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
async function search(reset=true){if(reset){page=1;selected.clear();applied=filter()}const seq=++querySeq;const r=await api('query',{filter:applied,page});if(seq!==querySeq)return;visible=r.rows;pages=r.pages;$('resultCount').textContent=`筛选结果 ${r.total.toLocaleString()} 篇`;$('rows').innerHTML=visible.map((row,i)=>`<tr><td class="checkbox-cell"><input type="checkbox" data-key="${row._key}" aria-label="勾选 ${escapeHTML(row.标题)}" ${selected.has(row._key)?'checked':''}></td><td><button class="article-title" data-detail="${i}">${escapeHTML(row.标题)}</button><div class="article-meta">${escapeHTML(row.公众号)}${row.所属合集?' · '+escapeHTML(row.所属合集):''}</div></td><td>${escapeHTML(row.发布时间||'未获取')}</td><td>${escapeHTML(row.作者||'—')}</td><td>${row.是否原创?`<span class="badge">${escapeHTML(row.是否原创)}</span>`:'—'}</td><td>${safeLink(row.链接)?`<a href="${escapeHTML(safeLink(row.链接))}" target="_blank" rel="noopener noreferrer">原文 ↗</a>`:'—'}</td></tr>`).join('');$('empty').hidden=r.total!==0;renderEmpty();$('pageInfo').textContent=`第 ${page} / ${pages} 页 · 每页 40 篇`;$('prevBtn').disabled=page<=1;$('nextBtn').disabled=page>=pages;updateSelection()}
function updateSelection(){$('selectedCount').textContent=selected.size?`已勾选 ${selected.size} 篇`:'';$('exportSelectedBtn').disabled=!selected.size;$('selectPage').checked=visible.length>0&&visible.every(r=>selected.has(r._key));$('selectPage').indeterminate=visible.some(r=>selected.has(r._key))&&!$('selectPage').checked}
function renderEmpty(){
 const targets=state.accounts.filter(a=>!applied.accounts?.length||applied.accounts.includes(a.name));
 const count=targets.reduce((n,a)=>n+(a.articleCount??0),0);
 if(count){$('empty').innerHTML='<strong>没有符合条件的文章</strong><p>这些公众号已有 '+count+' 篇文章，试试放宽日期或减少关键词。</p>';return}
 const configured=targets.some(a=>a.feed);
 $('empty').innerHTML='<strong>所选公众号还没有文章入库</strong><p>'+(configured?'采集来源已配置，先点击下面的按钮收集文章。':'先添加公众号的合集 / RSS 地址，或导入已有文章表。')+'</p><button class="primary" id="emptyAction">'+(configured?'立即收集':'配置采集来源')+'</button>';
 $('emptyAction').onclick=()=>configured?$('collectBtn').click():$('sourcesBtn').click();
}
function renderSources(){$('sourceList').innerHTML=state.accounts.map((a,i)=>`<div class="source-item"><div><strong>${escapeHTML(a.name)}</strong><small>${a.feed?escapeHTML(a.feed):'未配置合集 / RSS · 可导入文章或粘贴链接'}</small></div><button data-edit="${i}">编辑</button></div>`).join('');const chosen=filter().accounts;const targets=state.accounts.filter(a=>a.feed&&(!chosen.length||chosen.includes(a.name)));$('feedState').innerHTML=targets.length?targets.map(a=>`<div class="source-item">${escapeHTML(a.name)}</div>`).join(''):'<p>尚未配置来源。请先到“管理公众号”填写微信公众号合集链接或 RSS 地址。</p>'}
function detail(i){const row=visible[i];$('detail').innerHTML=`<h3 class="detail-title">${escapeHTML(row.标题)}</h3><dl class="detail-fields">${['公众号','发布时间','作者','是否原创','所属合集','摘要'].map(k=>`<dt>${k}</dt><dd>${escapeHTML(row[k]||'未获取')}</dd>`).join('')}<dt>采集来源</dt><dd>${escapeHTML(row._source)}</dd><dt>入库时间</dt><dd>${escapeHTML(row._collected.replace('T',' '))}</dd></dl><h3>文章正文</h3><div class="detail-content">${escapeHTML(row.文章内容||'这篇文章尚未获取正文。原表中的标题、链接等信息仍然可以筛选和导出。')}</div>`;$('detailDialog').showModal()}
async function exportFile(onlySelected){const button=$(onlySelected?'exportSelectedBtn':'exportBtn'),label=button.textContent;button.disabled=true;button.textContent='正在生成 Excel…';try{const blob=await api('export',{filter:applied,keys:onlySelected?[...selected]:null},true);const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=`公众号文章_${new Date().toLocaleDateString('sv-SE')}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);status('Excel 已生成，浏览器已开始下载。导出的是当前列表对应的筛选结果。')}catch(e){fail(e)}finally{button.disabled=false;button.textContent=label;updateSelection()}}
$('accounts').onchange=()=>search().catch(fail);
$('applyBtn').onclick=()=>search().catch(fail);
$('resetBtn').onclick=()=>{setFilter();$('preset').value='';search().catch(fail)};
$('preset').onchange=()=>{const p=state.presets[Number($('preset').value)];if($('preset').value!==''&&p){setFilter(p.filter);search().catch(fail)}};
$('saveBtn').onclick=()=>{$('presetName').value=$('preset').value!==''?state.presets[Number($('preset').value)]?.name||'':'';$('saveDialog').showModal()};
$('presetForm').onsubmit=async e=>{e.preventDefault();try{const name=$('presetName').value.trim();await api('preset',{name,filter:filter()});await loadState();$('preset').value=String(state.presets.findIndex(x=>x.name===name));$('saveDialog').close();status('筛选方案已保存在本机。')}catch(e){fail(e)}};
$('sourcesBtn').onclick=()=>{renderSources();$('sourcesDialog').showModal()};
$('sourceList').onclick=e=>{const b=e.target.closest('[data-edit]');if(b){const a=state.accounts[Number(b.dataset.edit)];$('accountName').value=a.name;$('feedUrl').value=a.feed;$('accountMessage').textContent='编辑后点击保存。'}};
$('accountForm').onsubmit=async e=>{e.preventDefault();try{const name=$('accountName').value.trim(),feed=$('feedUrl').value.trim();await api('account',{name,feed});await loadState();const f=filter();f.accounts=[name];setFilter(f);await search();$('accountForm').reset();if(feed){$('sourcesDialog').close();renderSources();setMode('feeds');$('collectDialog').showModal();$('runCollect').click()}else{$('accountMessage').textContent='公众号已保存。填写合集 / RSS 地址后，才能自动收集。'}}catch(e){$('accountMessage').textContent=e.message}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.days);if(n){const end=new Date(),start=new Date();start.setDate(start.getDate()-n+1);$('end').value=end.toLocaleDateString('sv-SE');$('start').value=start.toLocaleDateString('sv-SE')}else{$('start').value=$('end').value=''}search().catch(fail)});
$('prevBtn').onclick=()=>{if(page>1){page--;search(false).catch(fail)}};$('nextBtn').onclick=()=>{if(page<pages){page++;search(false).catch(fail)}};
$('rows').onclick=e=>{const b=e.target.closest('[data-detail]');if(b)detail(Number(b.dataset.detail))};
$('rows').onchange=e=>{if(e.target.dataset.key){e.target.checked?selected.add(e.target.dataset.key):selected.delete(e.target.dataset.key);updateSelection()}};
$('selectPage').onchange=()=>{visible.forEach(r=>$('selectPage').checked?selected.add(r._key):selected.delete(r._key));document.querySelectorAll('#rows input[data-key]').forEach(x=>x.checked=selected.has(x.dataset.key));updateSelection()};
$('exportBtn').onclick=()=>exportFile(false);$('exportSelectedBtn').onclick=()=>exportFile(true);
$('importBtn').onclick=()=>$('fileInput').click();
$('fileInput').onchange=async()=>{const f=$('fileInput').files[0];if(!f)return;if(f.size>16*1024*1024){status('文件超过 16 MB，请拆分后导入。',true);return}const label=$('importBtn').textContent;$('importBtn').disabled=true;$('importBtn').textContent='正在导入…';try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});const r=await api('import',{name:f.name,data,account:filter().accounts.length===1?filter().accounts[0]:''});await loadState();await search();status(`导入完成：新增 ${r.added} 篇，补充更新 ${r.updated} 篇，重复或无效 ${r.skipped} 篇。`)}catch(e){fail(e)}finally{$('importBtn').disabled=false;$('importBtn').textContent=label;$('fileInput').value=''}};
$('collectBtn').onclick=()=>{renderSources();setMode(state.accounts.some(a=>a.feed)?'feeds':'links');$('collectDialog').showModal()};
function setMode(m){mode=m;$('linksPanel').hidden=m!=='links';$('feedsPanel').hidden=m!=='feeds';$('linksTab').classList.toggle('active',m==='links');$('feedsTab').classList.toggle('active',m==='feeds')}
$('linksTab').onclick=()=>setMode('links');$('feedsTab').onclick=()=>setMode('feeds');
$('runCollect').onclick=async()=>{if(mode==='links'&&!$('articleLinks').value.trim()){$('jobMessage').textContent='请先粘贴文章链接。';return}$('runCollect').disabled=true;$('jobMessage').textContent='正在开始收集…';try{const r=await api('collect',{kind:mode,urls:$('articleLinks').value,accounts:filter().accounts});let job;do{await new Promise(r=>setTimeout(r,1000));job=await api('job',{id:r.id});$('jobMessage').textContent=`${job.done?'收集结束':'正在收集'}：${job.completed||0} / ${job.total||0} 个来源\n新增 ${job.added||0} 篇，更新 ${job.updated||0} 篇，跳过重复 ${job.skipped||0} 篇。`+(job.errors?.length?'\n\n未完成的来源：\n'+job.errors.join('\n\n'):'')}while(!job.done);await loadState();await search();status(job.errors?.length?`采集结束：新增 ${job.added||0} 篇；${job.errors.length} 个来源未完成，请查看“收集文章”中的原因。`:`采集完成：新增 ${job.added||0} 篇，更新 ${job.updated||0} 篇。`,!!job.errors?.length)}catch(e){$('jobMessage').textContent=e.message}finally{$('runCollect').disabled=false}};
loadState().then(()=>search()).catch(fail);
fetch('/health').then(r=>r.json()).then(h=>{$('exitAppBtn').hidden=!h.desktop}).catch(()=>{});
$('exitAppBtn').onclick=async()=>{try{await api('shutdown');document.body.innerHTML='<main><section class="workspace"><h1>拾文已退出</h1><p>文章和配置已保存在本机，可以关闭此页面。下次双击桌面上的“拾文”继续使用。</p></section></main>'}catch(e){fail(e)}};
